import java.util.stream.IntStream;

public class Productos {
  public static void main(String[] args) {
      int[] arr = {1, 2, 3, 4};

      // En Java, los Streams no tienen una función .prod() lista para usar.
      // Hay que proveerle una lambda de reducción matemática manual:
      int producto = IntStream.of(arr)
                              .reduce(1, (acumulador, actual) -> acumulador * actual);

      System.out.println(producto);
  }
}
